//! Theme selection over the generated Alembic tokens.
//!
//! [`tokens`] is generated by `cargo xtask tokens` from `design/tokens.json` and must not be
//! edited by hand. The design is dark first; the light palette exists for completeness and
//! for users who follow a light system appearance.

pub mod tokens;

use serde::{Deserialize, Serialize};

use self::tokens::Palette;

/// Which palette the user wants.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ThemePreference {
    /// Always dark (the default: the design is dark first).
    #[default]
    Dark,
    /// Always light.
    Light,
    /// Follow the system appearance.
    System,
}

impl ThemePreference {
    /// The palette to paint with, given whether the system appearance is dark.
    pub fn palette(self, system_is_dark: bool) -> &'static Palette {
        match self {
            Self::Dark => &tokens::DARK,
            Self::Light => &tokens::LIGHT,
            Self::System if system_is_dark => &tokens::DARK,
            Self::System => &tokens::LIGHT,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn dark_is_the_default_and_system_follows_the_appearance() {
        assert_eq!(ThemePreference::default(), ThemePreference::Dark);
        assert_eq!(ThemePreference::Dark.palette(false), &tokens::DARK);
        assert_eq!(ThemePreference::Light.palette(true), &tokens::LIGHT);
        assert_eq!(ThemePreference::System.palette(true), &tokens::DARK);
        assert_eq!(ThemePreference::System.palette(false), &tokens::LIGHT);
    }

    #[test]
    fn window_and_rail_sizes_match_the_design() {
        assert_eq!(tokens::size::DEFAULT_WINDOW, (1440.0, 900.0));
        assert_eq!(tokens::size::MIN_WINDOW, (960.0, 640.0));
        assert_eq!(tokens::size::SIDEBAR, 232.0);
        assert_eq!(tokens::KINDS.len(), 8);
    }
}
